function teleportE(e,nx,ny,col,n){if(!canMv(nx,ny,e.r))return false;
  const ox=e.x,oy=e.y,r=e.r||12;
  const _cr=parseInt(col.slice(1,3),16)||160,_cg=parseInt(col.slice(3,5),16)||0,_cb=parseInt(col.slice(5,7),16)||255;
  // ── 출발지: 흡입 내파 ──
  for(let i=0;i<10;i++){const a=Math.PI*2*i/10,d2=r*2.5;poolPart(ox+Math.cos(a)*d2,oy+Math.sin(a)*d2,-Math.cos(a)*5,-Math.sin(a)*5,col,2+Math.random()*2,8)}
  poolPart(ox,oy,0,0,col,r*1.6,8,3,0,0);
  _addBlastLight(ox,oy,r*3,8,_cr,_cg,_cb);
  // ── 출발지 연기 (퍼지며 사라짐) ──
  _addTpSmoke(ox,oy,r*4,18,0);
  e.x=nx;e.y=ny;
  // ── 착지 강타: 도착 조준범위 내 플레이어 타격 (돌진 e.atk*30 대비 35% = e.atk*10.5, 비보스 한정) ──
  if(!e.ib&&P.iframes<=0&&P.s!=='charge'){
    const _landR=(r+10)*2;
    if(dst(P.x,P.y,nx,ny)<_landR+P.r){
      hurtP(~~(e.atk*10.5*elMul(e.el,ar().el)));eModHitP(e);
      const _la=Math.atan2(P.y-ny,P.x-nx);P.kb.x+=Math.cos(_la)*120;P.kb.y+=Math.sin(_la)*120;
      addTxt(P.x,P.y-25,_T('충격파!'),col,30);
    }
  }
  // ── 도착지: 충격파 폭발 ──
  const isBig=e.ib||r>=18; // 보스/대형
  const pN=isBig?18:12,ringR=isBig?r*6:r*4.4; // 충격파 범위 2배
  // 1) 방사 파티클 (빠른 속도로 퍼짐 — 사거리 2배)
  for(let i=0;i<pN;i++){const a=Math.PI*2*i/pN,sp=10+Math.random()*12;poolPart(nx,ny,Math.cos(a)*sp,Math.sin(a)*sp,i%3===0?'#ffffff':col,2+Math.random()*3,12+~~(Math.random()*6))}
  // 2) 충격파 링 (크게)
  poolPart(nx,ny,0,0,col,ringR,10,3,0,0);
  poolPart(nx,ny,0,0,'#ffffff',ringR*.5,6,3,0,0);
  // 3) 바닥 균열선 4방향 (사거리 2배)
  for(let i=0;i<4;i++){const a=Math.PI*2*i/4+(Math.random()-.5)*.4;
    for(let j=1;j<=3;j++){const cd=r*1.6*j;poolPart(nx+Math.cos(a)*cd,ny+Math.sin(a)*cd,Math.cos(a)*(4+j*2),Math.sin(a)*(4+j*2),'#ffffff',1.5+Math.random(),8+j*2)}}
  // 4) 광원 폭발 (범위 2배)
  _addBlastLight(nx,ny,isBig?r*10:r*8,14,_cr,_cg,_cb);
  // 5) 화면 반응
  shake(isBig?8:4);
  e._tpFlashT=12;e._tpFlashCol=col;
  // 6) 스프라이트 도착 임펙트 (불꽃 폭발) + 보라색 버스트
  _addTpImpact(nx,ny,isBig?r*4:r*3,isBig?24:18,col);
  playVFXAng('teleport_burst',nx,ny,isBig?r/8:r/12,4,0,false);
  // 6b) 도착지 연기 (응축되며 나타남)
  _addTpSmoke(nx,ny,isBig?r*5:r*4,22,1);
  // 7) 출발→도착 번개 경로
  _addTpBolt(ox,oy,nx,ny,12,col);
  return true}

