function _emitEnemyShot(e,props){
  if(e._ch1StartMedium&&!_fieldEnemyCanShoot(e))return null;
  _prepareDarkSphere(props);
  if(e.s==='eShootWind'&&e.st2<=0&&e._swChargeEl===props.el&&!props.blackBean){props._commit=true;return spawnProj(props)}
  const list=G._shotWarnings||(G._shotWarnings=[]);
  const _parryClass=_projectileParryClass(props);
  let w=list.find(w=>w.owner===e&&w.frame===_gameFrame&&w.world===ens&&w.el===props.el&&w.blackBean===!!props.blackBean&&w.parryClass===_parryClass);
  if(!w||w.frame!==_gameFrame||w.world!==ens){
    const lane=list.filter(w=>w.owner===e&&w.world===ens).length;
    w={owner:e,world:ens,frame:_gameFrame,t:60,dead:!e.alive,x:e.x,y:e.y,r:(e.r||12)+lane*8,el:props.el,blackBean:!!props.blackBean,parryClass:_parryClass,col:_parryClass==='physical'?'#f4f4f4':props.col||'#ff6644',shots:[]};
