function _addTpBolt(ox,oy,dx,dy,dur,col){
  let b=null;for(let i=0;i<_TP_BOLT_MAX;i++){if(!_tpBolts[i].active){b=_tpBolts[i];break}}
  if(!b){let oi=0,ot=0;for(let i=0;i<_TP_BOLT_MAX;i++){const r=_tpBolts[i].t/_tpBolts[i].mt;if(r>ot){ot=r;oi=i}}b=_tpBolts[oi]}
  b.ox=ox;b.oy=oy;b.dx=dx;b.dy=dy;b.t=0;b.mt=dur||14;b.active=true;b.col=col||'#4488ff';
  // 번개 세그먼트 생성 (지그재그)
  b.segs=[];const steps=6+~~(Math.random()*4);
  const mx=(dx-ox)/steps,my=(dy-oy)/steps;
  let cx=ox,cy=oy;b.segs.push({x:cx,y:cy});
  for(let s=1;s<steps;s++){const off=20+Math.random()*15;const pa=Math.atan2(dy-oy,dx-ox)+Math.PI/2;
    cx=ox+mx*s+Math.cos(pa)*(Math.random()>.5?off:-off);cy=oy+my*s+Math.sin(pa)*(Math.random()>.5?off:-off);b.segs.push({x:cx,y:cy})}
  b.segs.push({x:dx,y:dy})}

