    _drawShootCharge(w.dead?w.x:e.x,w.dead?w.y:e.y,w.r,1-w.t/60,_wPhysical?'#f4f4f4':w.blackBean?_BEAN_RAINBOW[(_gameFrame>>2)%7]:w.col,1,_wPhysical);
    if(_wPhysical)_drawProjectileChargeLabel(w.dead?w.x:e.x,w.dead?w.y:e.y,w.r,_L('물리탄 차징 · E로 패링','PHYSICAL SHOT CHARGING · PARRY WITH E'));
  }
}

