function _drawShootCharge(x,y,r,prog,col,sa,physical=false){
  if(sa==null)sa=1;
  prog=prog<0?0:prog>1?1:prog;
  const R=r+10;
  X.save();
  X.lineCap='round';
  X.globalAlpha=sa*.28;X.strokeStyle='#080808';X.lineWidth=5;
  X.beginPath();X.arc(x,y,R,0,Math.PI*2);X.stroke();
  if(prog>0){
    X.globalAlpha=physical?sa:sa*(.8+prog*.2);X.strokeStyle=physical?'#ffffff':col||'#ff6644';X.lineWidth=physical?6:3.5;
    X.beginPath();X.arc(x,y,R,-Math.PI/2,-Math.PI/2+Math.PI*2*prog);X.stroke();
  }
  X.restore();
}
